      <nav aria-label="管理端主导航"><RouterLink v-for="item in navItems" :key="item.key" class="portal-nav" :class="{ active: activeTab === item.key }" :aria-current="activeTab === item.key ? 'page' : undefined" :to="`/admin/${item.path}`"><AppIcon :name="item.icon" /><span>{{ item.label }}</span></RouterLink></nav>
      <div class="portal-sidebar__footer"><span class="avatar">管</span><span><strong>{{ session.displayName }}</strong><small>管理员</small></span></div>
