      <div v-if="['permissions', 'ai', 'organizations'].includes(activeTab)" class="version-bar" aria-label="系统设置分区">
        <div><RouterLink class="outline-button" to="/admin/settings">权限管理</RouterLink><RouterLink class="outline-button" to="/admin/organizations">组织班级</RouterLink><RouterLink class="outline-button" to="/admin/ai">AI 评价规则</RouterLink></div>
      </div>
      <div v-if="activeTab === 'courses'" class="version-bar"><span>课程篇与表达技巧训练</span><RouterLink class="outline-button" to="/admin/broadcast-scripts">广播词库</RouterLink><RouterLink class="outline-button" to="/admin/tasks">任务管理 →</RouterLink></div>
      <p v-if="pageError" class="notice notice--error" role="alert">{{ pageError }}</p>
      <template v-if="activeTab === 'dashboard'">
        <div class="metric-grid metric-grid--four"><article class="metric-card"><span>任务分配</span><strong>{{ summary.assignment_count }}</strong><small>真实任务分配</small></article><article class="metric-card"><span>进行中任务</span><strong>{{ summary.published_count }}</strong><small>练习 {{ summary.practice_count }} · 考试 {{ summary.exam_count }}</small></article><article class="metric-card"><span>课程</span><strong>{{ courses.length }}</strong><small>{{ publishedVersions.length }} 个已发布版本</small></article><article class="metric-card"><span>完成率</span><strong>{{ summary.completion_rate }}%</strong><small>按已分配任务计算</small></article></div>
        <section class="panel quick-actions"><div><h2>快速操作</h2><p>课程标准库 → 训练任务</p></div><button class="quick-action quick-action--practice" @click="openTaskDialog('practice')"><strong>+ 练习任务</strong><small>即时反馈 · 反复纠正 · 进步记录</small></button><button class="quick-action quick-action--exam" @click="openTaskDialog('exam')"><strong>+ 考试任务</strong><small>限次录音 · 整卷提交 · 人工测评</small></button></section>
        <section class="panel"><div class="panel__heading"><div><h2>最近任务</h2><p>查看最新发布状态与完成进度</p></div><button class="outline-button" @click="refreshAll">刷新</button></div><TaskManagementPanel compact :tasks="tasks.slice(0, 5)" :courses="courses" :course-versions="publishedVersions" :broadcast-scripts="broadcastScripts" @status="changeTaskStatus" @delete="deleteTask" /></section>
        <section class="panel unassigned-panel"><div class="panel__heading"><div><h2>未分配教员</h2><p>音频已保存，绑定教员后可重新分配评价任务</p></div><button v-if="unassignedEvaluations.length" class="outline-button" @click="refreshAll">刷新</button></div><div v-if="unassignedEvaluations.length" class="unassigned-list"><article v-for="item in unassignedEvaluations.slice(0, 8)" :key="item.id"><span class="type-pill" :class="item.review_type">{{ item.review_type === 'practice' ? '练习' : '考试' }}</span><strong>{{ item.learner_name }}</strong><small>{{ formatDate(item.created_at) }}</small></article></div><div v-else class="empty-panel">暂无未分配教员的提交</div></section>
      </template>

      <template v-else-if="activeTab === 'organizations'">
        <section class="panel organization-toolbar"><div class="panel__heading"><div><h2>组织与班级</h2><p>班级用于批量组织学员；教员关系按学员记录并支持批量绑定</p></div><button class="primary-button primary-button--compact" @click="dialog = 'organization'">+ 新建组织</button></div></section>
        <ClassManagementPanel v-model:selected-organization-id="selectedOrganizationId" :organizations="organizations" :classes="classes" :users="users" @changed="refreshAll" />
      </template>

      <template v-else-if="activeTab === 'learners'">
        <UserManagementPanel :users="users" :classes="classes" :current-permissions="currentPermissions" :current-user-id="session.user?.id" @changed="refreshAll" />
      </template>

      <template v-else-if="activeTab === 'courses'">
        <CourseV23ManagementPanel :organizations="organizations" :classes="classes" @changed="refreshAll" @create-task="openCourseTaskDialog" />
        <section class="panel legacy-content-note"><strong>历史内容已保留</strong><p>旧课程标准、学习卡片、PPT/PDF/HTML 和已发布任务仍正常运行，但不再作为新建课程入口展示。</p></section>
      </template>

      <template v-else-if="activeTab === 'prosody'"><ProsodyStudioPanel /></template>

      <template v-else-if="activeTab === 'tasks'"><TaskManagementPanel :tasks="tasks" :courses="courses" :course-versions="publishedVersions" :broadcast-scripts="broadcastScripts" @create="openTaskDialog" @status="changeTaskStatus" @delete="deleteTask" /></template>

      <template v-else-if="activeTab === 'permissions'">
        <div class="permission-layout">
          <section class="panel"><div class="panel__heading"><div><h2>角色权限矩阵</h2><p>权限由服务端 RBAC 统一校验，页面不使用前端伪权限</p></div></div><div class="permission-table"><div class="permission-row permission-head"><strong>能力</strong><span>学员</span><span>测评员</span><span>教员</span><span>管理员</span></div><div v-for="row in permissionMatrix" :key="row.label" class="permission-row"><strong>{{ row.label }}<small>{{ row.permission }}</small></strong><span v-for="(allowed,index) in row.roles" :key="index" :class="allowed ? 'allowed' : 'denied'">{{ allowed ? '可用' : '—' }}</span></div></div></section>
          <section class="panel"><div class="panel__heading"><div><h2>当前登录权限</h2><p>来自真实会话与产品成员关系</p></div></div><div class="permission-chip-list"><span v-for="permission in currentPermissions" :key="permission">{{ permission }}</span><div v-if="!currentPermissions.length" class="empty-panel">当前会话未返回权限</div></div><p class="security-note"><AppIcon name="lock" /> 角色变更必须通过审计接口执行，不在浏览器中直接修改数据库。</p></section>
        </div>
      </template>

      <template v-else-if="activeTab === 'ai'">
        <div class="ai-console-grid">
          <section class="ai-console-hero"><div><span class="page-kicker">AI Gateway</span><h2>{{ aiStatus?.enabled ? 'AI 评价能力已启用' : 'AI 评价能力待配置' }}</h2><p>完整度、发音、流畅度与表达质量由独立适配器生成证据，不生成假分数。</p></div><AppIcon name="ai" /></section>
          <AIProviderSettingsPanel @changed="loadAIStatus" />
          <section class="panel"><div class="panel__heading"><div><h2>能力适配器</h2><p>服务器实时状态</p></div><button class="outline-button" @click="loadAIStatus">刷新</button></div><div v-if="aiStatus" class="adapter-list"><article v-for="adapter in aiStatus.adapters" :key="adapter.name"><AppIcon :name="adapter.configured ? 'check' : 'connection'" /><div><strong>{{ adapterLabel(adapter.name) }}</strong><small>{{ adapter.provider || '讯飞或未配置供应商' }}<template v-if="adapter.version"> · {{ adapter.version }}</template></small></div><span class="ui-status" :class="adapter.configured ? 'success' : 'warning'">{{ adapter.configured ? '已配置' : '待配置' }}</span></article></div><div v-else class="empty-panel">正在读取 AI 状态…</div></section>
          <section class="panel"><div class="panel__heading"><div><h2>评价规则说明</h2><p>课程标准与 AI 证据的对应关系</p></div></div><div class="rule-dimension-grid"><article v-for="item in aiDimensions" :key="item.title"><AppIcon :name="item.icon" /><strong>{{ item.title }}</strong><p>{{ item.description }}</p></article></div><p class="security-note"><AppIcon name="settings" /> 密钥只通过服务器环境变量配置，管理页不读取、不展示密钥原文。</p></section>
        </div>
      </template>

      <template v-else>
        <div class="analytics-dashboard"><div class="metric-grid metric-grid--four"><article class="metric-card"><span>学员账号</span><strong>{{ learnerUsers.length }}</strong><small>真实成员数据</small></article><article class="metric-card"><span>课程版本</span><strong>{{ publishedVersions.length }}</strong><small>已发布标准</small></article><article class="metric-card"><span>任务完成</span><strong>{{ summary.completed_count }}</strong><small>共 {{ summary.assignment_count }} 份分配</small></article><article class="metric-card"><span>完成率</span><strong>{{ summary.completion_rate }}%</strong><small>按任务分配计算</small></article></div><div class="analytics-panels"><section class="panel"><div class="panel__heading"><div><h2>任务结构</h2><p>练习与考试发布情况</p></div></div><div class="donut-summary"><div class="donut" :style="{ '--practice-share': `${practiceShare}%` }"><strong>{{ summary.task_count }}</strong><span>总任务</span></div><dl><div><dt><i class="dot practice" />练习任务</dt><dd>{{ summary.practice_count }}</dd></div><div><dt><i class="dot exam" />考试任务</dt><dd>{{ summary.exam_count }}</dd></div><div><dt><i class="dot draft" />草稿/关闭</dt><dd>{{ Math.max(summary.task_count - summary.published_count, 0) }}</dd></div></dl></div></section><section class="panel"><div class="panel__heading"><div><h2>组织覆盖</h2><p>公司、班级与学员分布</p></div></div><div class="organization-bars"><article v-for="org in organizations" :key="org.id"><div><strong>{{ org.name }}</strong><span>{{ org.class_count }} 个班级</span></div><i><b :style="{ width: `${organizationWidth(org.class_count)}%` }" /></i></article><div v-if="!organizations.length" class="empty-panel">暂无组织数据</div></div></section></div></div>
      </template>
    </section>

    <div v-if="dialog" class="modal-backdrop" role="presentation" @click.self="closeDialog">
      <form v-if="dialog === 'organization'" class="modal-card" @submit.prevent="saveOrganization"><ModalTitle title="新建组织" text="建立公司级数据边界" @close="closeDialog"/><label>组织编码<input v-model.trim="organizationForm.code" required maxlength="80"></label><label>组织名称<input v-model.trim="organizationForm.name" required maxlength="200"></label><ModalActions :saving="saving" @close="closeDialog"/></form>
      <form v-else-if="dialog === 'course'" class="modal-card" @submit.prevent="saveCourse"><ModalTitle title="新建课程" text="课程发布采用不可变版本" @close="closeDialog"/><label>课程编码<input v-model.trim="courseForm.code" required maxlength="80" placeholder="如 CL-BROADCAST-001"></label><label>课程名称<input v-model.trim="courseForm.title" required maxlength="200"></label><label>所属组织<select v-model="courseForm.organization_id"><option value="">全平台公共课程</option><option v-for="item in organizations" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>课程说明<textarea v-model.trim="courseForm.description" rows="3"></textarea></label><ModalActions :saving="saving" @close="closeDialog"/></form>
      <form v-else-if="dialog === 'version'" class="modal-card" @submit.prevent="saveVersion"><ModalTitle title="创建课程版本" text="已发布版本不直接覆盖" @close="closeDialog"/><label>版本标识<input v-model.trim="versionForm.version_label" required maxlength="40" placeholder="如 V1.0"></label><label>变更说明<textarea v-model.trim="versionForm.change_summary" rows="3"></textarea></label><ModalActions :saving="saving" @close="closeDialog"/></form>
      <form v-else-if="dialog === 'chapter'" class="modal-card" @submit.prevent="saveChapter"><ModalTitle title="新增篇目" text="篇目属于当前课程版本" @close="closeDialog"/><label>篇目编码<input v-model.trim="chapterForm.code" required maxlength="80"></label><label>篇目名称<input v-model.trim="chapterForm.title" required maxlength="200"></label><label>顺序<input v-model.number="chapterForm.sequence_no" type="number" min="1" required></label><label>学习目标<textarea v-model.trim="chapterForm.learning_objective" rows="3"></textarea></label><ModalActions :saving="saving" @close="closeDialog"/></form>
      <form v-else-if="dialog === 'import'" class="modal-card modal-card--wide" @submit.prevent="saveHtml"><ModalTitle title="导入 HTML 课程内容" text="仅接收 .html/.htm；脚本和危险标签会被移除" @close="closeDialog"/><label>内容名称<input v-model.trim="htmlForm.title" required maxlength="200"></label><label>显示顺序<input v-model.number="htmlForm.sequence_no" type="number" min="1" required></label><label>HTML 文件<input type="file" accept=".html,.htm,text/html" required @change="readHtmlFile"></label><p v-if="htmlForm.source_filename" class="file-note">{{ htmlForm.source_filename }} · {{ htmlForm.source_html.length }} 字符</p><ModalActions :saving="saving" @close="closeDialog"/></form>
      <form v-else-if="dialog === 'ppt'" class="modal-card modal-card--wide" @submit.prevent="savePpt"><ModalTitle title="导入 PPTX 课程" text="每页转换为一个可学习篇目；请先完成草稿内容再发布版本" @close="closeDialog"/><div class="import-guidance"><strong>导入规则</strong><p>支持 PowerPoint .pptx，单个文件不超过 50 MB。系统保留幻灯片文字与顺序，并自动安全净化为 HTML；图片、动画和视频暂不导入。</p></div><label>PPTX 文件<input type="file" accept=".pptx,application/vnd.openxmlformats-officedocument.presentationml.presentation" required @change="readPptFile"></label><p v-if="pptFile" class="file-note">{{ pptFile.name }} · {{ Math.ceil(pptFile.size / 1024) }} KB · 将按幻灯片页数生成篇目</p><ModalActions :saving="saving" @close="closeDialog"/></form>
      <form v-else-if="dialog === 'standard'" class="modal-card modal-card--wide" @submit.prevent="saveStandard"><ModalTitle title="配置课程训练标准" text="每次保存生成新规则修订，历史版本不会删除" @close="closeDialog"/><label>标准朗读文本<textarea v-model.trim="standardForm.standard_text" rows="6" required maxlength="20000"></textarea></label><div class="standard-form-grid"><label>重音规则<textarea v-model.trim="standardForm.stress_rules" rows="3" placeholder="如：WELCOME、ABOARD 重读"></textarea></label><label>发音提示<textarea v-model.trim="standardForm.pronunciation_notes" rows="3" placeholder="如：注意 aboard 的元音"></textarea></label><label>停连规则<textarea v-model.trim="standardForm.pause_rules" rows="3" placeholder="如：Ladies and gentlemen / welcome aboard"></textarea></label><label>语气要求<textarea v-model.trim="standardForm.tone_requirements" rows="3" placeholder="如：亲切、清晰、专业"></textarea></label></div><label>标准音频（可选）<input type="file" accept="audio/wav,audio/mpeg,audio/mp4,audio/ogg,audio/webm,.wav,.mp3,.m4a,.ogg,.webm" @change="readStandardAudio"></label><label>规则版本<input v-model.trim="standardForm.rule_version" required maxlength="40"></label><label>修订说明<input v-model.trim="standardForm.change_summary" maxlength="2000"></label><ModalActions :saving="saving" @close="closeDialog"/></form>
      <form v-else-if="dialog === 'interaction'" class="modal-card modal-card--wide" @submit.prevent="saveInteraction"><ModalTitle :title="editingInteraction ? '编辑互动练习' : '添加互动练习'" text="互动配置保存在当前草稿版本，发布版本后学员可见" @close="closeDialog"/><label>互动类型<select v-model="interactionForm.interaction_type"><option value="hotspot">点击互动（卡片热点）</option><option value="choice">选择题</option><option value="fill_blank">填空题</option></select></label><label>标题<input v-model.trim="interactionForm.title" required maxlength="200" placeholder="如：选择正确的客舱表达"></label><label>题干/提示<textarea v-model.trim="interactionForm.prompt" rows="3" required maxlength="4000" placeholder="学员需要完成什么？"></textarea></label><label v-if="interactionForm.interaction_type !== 'fill_blank'">选项（每行一个）<textarea v-model="interactionOptionsText" rows="4" placeholder="Welcome aboard\nGoodbye\nPlease sit down"></textarea></label><label v-if="interactionForm.interaction_type !== 'fill_blank'">正确选项<input v-model.trim="interactionForm.correct_answer" required placeholder="填写上面某一行的完整内容"></label><label v-else>可接受答案（每行一个）<textarea v-model="interactionAnswersText" rows="3" placeholder="welcome aboard\nWelcome aboard"></textarea></label><label>答对反馈<textarea v-model.trim="interactionForm.feedback_correct" rows="2"></textarea></label><label>答错反馈<textarea v-model.trim="interactionForm.feedback_incorrect" rows="2"></textarea></label><div class="interaction-form-grid"><label>显示顺序<input v-model.number="interactionForm.sequence_no" type="number" min="1" required></label><label class="check-row"><input v-model="interactionForm.required" type="checkbox"> 必须完成后才能算本篇达标</label></div><ModalActions :saving="saving" @close="closeDialog"/></form>
      <form v-else-if="dialog === 'user'" class="modal-card" @submit.prevent="saveUser"><ModalTitle title="新增账号" text="创建产品成员与服务端角色" @close="closeDialog"/><label>账号/工号<input v-model.trim="userForm.account" required></label><label>姓名<input v-model.trim="userForm.display_name" required></label><label>初始密码<input v-model="userForm.password" type="password" minlength="10" required></label><label>角色<select v-model="userForm.role"><option value="learner">学员</option><option value="evaluator">测评员</option><option value="instructor">教员</option><option value="admin">管理员</option></select></label><label>班级<select v-model="userForm.class_id"><option value="">暂不分班</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><ModalActions :saving="saving" @close="closeDialog"/></form>
      <form v-else-if="dialog === 'task'" class="modal-card modal-card--wide modal-card--task" @submit.prevent="saveTask"><ModalTitle :title="`创建${taskForm.type === 'practice' ? '练习' : '考试'}任务`" :text="taskForm.type === 'practice' ? '反复练习、即时反馈和进步记录' : '限次录音、整卷提交和成绩发布'" @close="closeDialog"/><label>任务名称<input v-model.trim="taskForm.title" required></label><label>内容来源<select v-model="taskForm.sourceMode"><option value="course">已发布课程版本</option><option value="broadcast">已启用广播词</option></select></label><label v-if="taskForm.sourceMode === 'course'">课程版本<select v-model="taskForm.courseVersionId" required><option value="" disabled>请选择</option><option v-for="item in publishedVersions" :key="item.id" :value="item.id">{{ courseTitle(item.course_id) }} · {{ item.version_label }}</option></select></label><div v-else class="broadcast-batch-picker"><div class="broadcast-batch-picker__heading"><div><strong>广播词（可多选）</strong><small>选中的篇目会合并到同一个任务，学员按顺序完成。</small></div><div><button type="button" @click="toggleAllBroadcastScripts">{{ allBroadcastScriptsSelected ? '取消全选' : '全选' }}</button><button v-if="taskForm.broadcastScriptIds.length" type="button" @click="taskForm.broadcastScriptIds = []">清空</button></div></div><div class="broadcast-batch-picker__list"><label v-for="item in broadcastScripts" :key="item.id" class="check-row broadcast-option" :class="{ selected: taskForm.broadcastScriptIds.includes(item.id) }"><input v-model="taskForm.broadcastScriptIds" type="checkbox" :value="item.id"><span><strong>{{ item.title }}</strong><small>{{ item.language === 'zh_cn' ? '中文' : item.language === 'en' ? '英文' : item.language }} · {{ item.slice_count }} 段</small></span></label><p v-if="!broadcastScripts.length" class="field-hint">暂无已启用广播词</p></div><p class="broadcast-selection-summary">已选择 {{ taskForm.broadcastScriptIds.length }} 篇<template v-if="taskForm.broadcastScriptIds.length > 1">，将创建 1 个组合任务</template></p></div><label>截止时间<input v-model="taskForm.dueAt" type="datetime-local"></label><label v-if="taskForm.type === 'practice'">最少练习次数<input v-model.number="taskForm.minAttempts" type="number" min="1" max="99"></label><label v-else>最大录音次数<input v-model.number="taskForm.maxRecordings" type="number" min="1" max="10"></label><div class="target-grid"><div class="user-picker"><strong>按班级发布</strong><small>{{ taskForm.type === 'practice' ? '仅可选择训练班' : '仅可选择考核班' }}</small><label v-for="item in targetClasses" :key="item.id" class="check-row"><input v-model="taskForm.classIds" type="checkbox" :value="item.id">{{ item.name }} · {{ item.member_count }} 人</label><p v-if="!targetClasses.length" class="field-hint">暂无匹配类型的启用班级</p></div><div class="user-picker"><strong>补充指定学员</strong><small>可与班级同时选择，系统会自动去重</small><label v-for="user in learnerUsers" :key="user.id" class="check-row"><input v-model="taskForm.userIds" type="checkbox" :value="user.id">{{ user.display_name }}</label></div></div><ModalActions :saving="saving" @close="closeDialog"/></form>
      <p v-if="dialogError" class="dialog-error">{{ dialogError }}</p>
    </div>
  </main>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import AppIcon from '@/components/AppIcon.vue'
import BrandMark from '@/components/BrandMark.vue'
import UserManagementPanel from '@/components/UserManagementPanel.vue'
import ClassManagementPanel from '@/components/ClassManagementPanel.vue'
import TaskManagementPanel from '@/components/TaskManagementPanel.vue'
import CourseV23ManagementPanel from '@/components/CourseV23ManagementPanel.vue'
import AIProviderSettingsPanel from '@/components/AIProviderSettingsPanel.vue'
import ProsodyStudioPanel from '@/components/ProsodyStudioPanel.vue'
import ModalTitle from '@/components/AdminModalTitle.vue'
import ModalActions from '@/components/AdminModalActions.vue'
import { cabinlingoApi, type AIGatewayStatus, type BroadcastScript, type Chapter, type ContentInteraction, type ContentItem, type Course, type CourseStandard, type CourseVersion, type DashboardSummary, type Organization, type TaskListItem, type TrainingClass, type UserSummary } from '@/api'
import { useSessionStore } from '@/stores/session'

type Tab = 'dashboard' | 'organizations' | 'learners' | 'courses' | 'prosody' | 'broadcasts' | 'tasks' | 'permissions' | 'ai' | 'analytics'; type Dialog = 'organization' | 'class' | 'course' | 'version' | 'chapter' | 'import' | 'ppt' | 'standard' | 'interaction' | 'user' | 'task' | null
const route = useRoute(); const router = useRouter(); const session = useSessionStore()
const navItems: { key: Tab; path: string; label: string; icon: string }[] = [
  { key: 'dashboard', path: 'dashboard', label: '工作台', icon: 'dashboard' },
  { key: 'learners', path: 'users', label: '学员管理', icon: 'users' },
  { key: 'tasks', path: 'tasks', label: '任务管理', icon: 'tasks' },
  { key: 'courses', path: 'courses', label: '课程内容', icon: 'course' },
  { key: 'prosody', path: 'prosody', label: '音频制作', icon: 'microphone' },
  { key: 'analytics', path: 'analytics', label: '统计报表', icon: 'trend' },
  { key: 'permissions', path: 'settings', label: '系统设置', icon: 'settings' },
]

const routeToTab: Record<string, Tab> = { dashboard: 'dashboard', organizations: 'organizations', users: 'learners', courses: 'courses', prosody: 'prosody', tasks: 'tasks', settings: 'permissions', permissions: 'permissions', ai: 'ai', analytics: 'analytics' }
const activeTab = computed<Tab>(() => routeToTab[String(route.params.section || 'dashboard')] || 'dashboard'); const dialog = ref<Dialog>(null); const saving = ref(false); const pageError = ref(''); const dialogError = ref(''); const tasks = ref<TaskListItem[]>([]); const broadcastScripts = ref<BroadcastScript[]>([]); const users = ref<UserSummary[]>([]); const organizations = ref<Organization[]>([]); const classes = ref<TrainingClass[]>([]); const courses = ref<Course[]>([]); const publishedVersions = ref<CourseVersion[]>([]); const unassignedEvaluations = ref<Array<{ id: string; review_type: 'practice' | 'exam'; learner_name: string; created_at: string }>>([]); const aiStatus = ref<AIGatewayStatus | null>(null)
const selectedOrganizationId = ref(''); const selectedCourse = ref<Course | null>(null); const versions = ref<CourseVersion[]>([]); const selectedVersion = ref<CourseVersion | null>(null); const chapters = ref<Chapter[]>([]); const selectedChapter = ref<Chapter | null>(null); const contents = ref<ContentItem[]>([]); const selectedContent = ref<ContentItem | null>(null); const courseCardViewerUrl = ref(''); const selectedStandard = ref<CourseStandard | null>(null); const interactions = ref<ContentInteraction[]>([]); const editingInteraction = ref<ContentInteraction | null>(null); const standardAudioFile = ref<File | null>(null); const standardAudioPreview = ref(''); const summary = reactive<DashboardSummary>({ task_count: 0, practice_count: 0, exam_count: 0, published_count: 0, assignment_count: 0, completed_count: 0, completion_rate: 0 })
const organizationForm = reactive({ code: '', name: '' }); const courseForm = reactive({ code: '', title: '', description: '', organization_id: '' }); const versionForm = reactive({ version_label: 'V1.0', change_summary: '' }); const chapterForm = reactive({ code: '', title: '', sequence_no: 1, learning_objective: '' }); const htmlForm = reactive({ title: '', sequence_no: 1, source_filename: '', source_html: '' }); const pptFile = ref<File | null>(null); const standardForm = reactive({ standard_text: '', stress_rules: '', pronunciation_notes: '', pause_rules: '', tone_requirements: '', rule_version: '1.0', change_summary: '' }); const interactionForm = reactive({ interaction_type: 'hotspot' as 'choice' | 'hotspot' | 'fill_blank', title: '互动练习', prompt: '', options: [] as string[], correct_answer: '', accepted_answers: [] as string[], feedback_correct: '回答正确，继续保持。', feedback_incorrect: '再看一下课程内容，再试一次。', required: true, sequence_no: 1 }); const interactionOptionsText = ref(''); const interactionAnswersText = ref(''); const userForm = reactive({ account: '', display_name: '', password: '', role: 'learner' as 'learner' | 'evaluator' | 'instructor' | 'admin', class_id: '' }); const taskForm = reactive({ type: 'practice' as 'practice' | 'exam', title: '', sourceMode: 'course' as 'course' | 'broadcast', broadcastScriptIds: [] as string[], courseVersionId: '', dueAt: '', minAttempts: 1, maxRecordings: 1, userIds: [] as string[], classIds: [] as string[] })
const pageTitle = computed(() => navItems.find(item => item.key === activeTab.value)?.label || '工作台'); const learnerUsers = computed(() => users.value.filter(user => user.roles.includes('learner'))); const targetClasses = computed(() => classes.value.filter(item => item.status === 'active' && item.class_type === (taskForm.type === 'practice' ? 'training' : 'assessment')))
const allBroadcastScriptsSelected = computed(() => broadcastScripts.value.length > 0 && taskForm.broadcastScriptIds.length === broadcastScripts.value.length)
const currentPermissions = computed(() => session.user?.memberships.find(item => item.product === 'cabinlingo')?.permissions || [])
const permissionMatrix = [{ label: '查看与完成训练', permission: 'cabinlingo:read', roles: [true, true, true, true] }, { label: '提交录音与练习', permission: 'cabinlingo:learn', roles: [true, false, false, true] }, { label: '教员专业评价', permission: 'cabinlingo:review', roles: [false, true, true, true] }, { label: '管理课程与任务', permission: 'cabinlingo:task.manage', roles: [false, false, true, true] }, { label: '删除账号（停用）', permission: 'cabinlingo:user.delete', roles: [false, false, false, true] }, { label: '重置账号密码', permission: 'cabinlingo:user.password_reset', roles: [false, false, false, true] }, { label: '批量导入账号', permission: 'cabinlingo:user.import', roles: [false, false, false, true] }, { label: '组织、账号和权限', permission: 'cabinlingo:admin', roles: [false, false, false, true] }]
const aiDimensions = [{ title: '完整度', icon: 'document', description: '漏读、增读、替换与标准文本对齐。' }, { title: '发音质量', icon: 'microphone', description: '音素、单词发音和语音清晰度。' }, { title: '流畅度', icon: 'trend', description: '语速、停顿、节奏与停连规则。' }, { title: '表达质量', icon: 'chat', description: '语义符合度、专业表达和客舱语气。' }]
const practiceShare = computed(() => summary.task_count ? Math.round(summary.practice_count / summary.task_count * 100) : 0)
function logout() { session.signOut(); void router.replace('/login') } function courseTitle(id: string) { return courses.value.find(item => item.id === id)?.title || '课程' } function formatDate(value: string) { return new Date(value).toLocaleString('zh-CN', { dateStyle: 'short', timeStyle: 'short' }) } function closeDialog() { dialog.value = null; saving.value = false; dialogError.value = '' }
function adapterLabel(name: string) { return ({ asr_iat: '语音听写 / 完整度', ise: '语音评测 / 发音流畅度', suntone: '讯飞 Suntone 综合评测' } as Record<string, string>)[name] || name } function organizationWidth(count: number) { const max = Math.max(...organizations.value.map(item => item.class_count), 1); return Math.max(Math.round(count / max * 100), count ? 12 : 0) }
async function loadAIStatus() { try { aiStatus.value = await cabinlingoApi.aiStatus() } catch { pageError.value = 'AI 状态读取失败，请确认当前账号权限。' } }
function clearStandardAudio() { if (standardAudioPreview.value) URL.revokeObjectURL(standardAudioPreview.value); standardAudioPreview.value = '' }
async function selectContent(item: ContentItem | null) { clearStandardAudio(); selectedContent.value = item; courseCardViewerUrl.value = ''; if (item?.learning_card_id) { const viewer = await cabinlingoApi.previewLearningCard(item.learning_card_id); courseCardViewerUrl.value = viewer.viewer_url; selectedStandard.value = null; interactions.value = []; return } selectedStandard.value = item ? await cabinlingoApi.courseStandard(item.id) : null; interactions.value = item ? await cabinlingoApi.contentInteractions(item.id) : [] }
function openTaskDialog(type: 'practice' | 'exam') { Object.assign(taskForm, { type, title: '', sourceMode: publishedVersions.value.length ? 'course' : 'broadcast', broadcastScriptIds: broadcastScripts.value[0] ? [broadcastScripts.value[0].id] : [], courseVersionId: publishedVersions.value[0]?.id || '', dueAt: '', minAttempts: 1, maxRecordings: 1, userIds: [], classIds: [] }); dialog.value = 'task' } function toggleAllBroadcastScripts() { taskForm.broadcastScriptIds = allBroadcastScriptsSelected.value ? [] : broadcastScripts.value.map(item => item.id) }
function openCourseTaskDialog(courseVersionId: string) { openTaskDialog('practice'); taskForm.sourceMode = 'course'; taskForm.courseVersionId = courseVersionId; const version = publishedVersions.value.find(item => item.id === courseVersionId); if (version) taskForm.title = `${courseTitle(version.course_id)}练习` }
async function readHtmlFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (!/\.html?$/i.test(file.name)) { dialogError.value = '只允许 .html 或 .htm 文件'; return } htmlForm.source_filename = file.name; htmlForm.title ||= file.name.replace(/\.html?$/i, ''); htmlForm.source_html = await file.text() }
function readPptFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0] || null; if (!file) return; if (!/\.pptx$/i.test(file.name)) { dialogError.value = '只允许 .pptx 文件；旧版 .ppt 请先另存为 .pptx'; pptFile.value = null; return } if (file.size > 50 * 1024 * 1024) { dialogError.value = 'PPTX 文件不能超过 50 MB'; pptFile.value = null; return } dialogError.value = ''; pptFile.value = file }
function readStandardAudio(event: Event) { const file = (event.target as HTMLInputElement).files?.[0] || null; if (file && file.size > 26214400) { dialogError.value = '标准音频不能超过 25 MB'; standardAudioFile.value = null; return } standardAudioFile.value = file }
async function refreshAll() { pageError.value = ''; const r = await Promise.allSettled([cabinlingoApi.dashboard(), cabinlingoApi.tasks(), cabinlingoApi.users(), cabinlingoApi.broadcastScripts({ enabled: true, archived: false, page_size: 100 }), cabinlingoApi.organizations(), cabinlingoApi.classes(), cabinlingoApi.courses(), cabinlingoApi.publishedCourseVersions(), cabinlingoApi.unassignedEvaluationTasks()]); if (r[0].status === 'fulfilled') Object.assign(summary, r[0].value); if (r[1].status === 'fulfilled') tasks.value = r[1].value; if (r[2].status === 'fulfilled') users.value = r[2].value; if (r[3].status === 'fulfilled') broadcastScripts.value = r[3].value.items; if (r[4].status === 'fulfilled') organizations.value = r[4].value; if (r[5].status === 'fulfilled') classes.value = r[5].value; if (r[6].status === 'fulfilled') courses.value = r[6].value; if (r[7].status === 'fulfilled') publishedVersions.value = r[7].value; if (r[8].status === 'fulfilled') unassignedEvaluations.value = r[8].value; if (r.some(item => item.status === 'rejected')) pageError.value = '部分管理数据未加载；请确认已执行最新数据库迁移并刷新。'; if (!selectedOrganizationId.value && organizations.value[0]) selectedOrganizationId.value = organizations.value[0].id }
async function runSave(action: () => Promise<void>, error: string) { saving.value = true; dialogError.value = ''; try { await action(); closeDialog(); await refreshAll() } catch (cause) { dialogError.value = error; saving.value = false; console.error(cause) } }
async function saveOrganization() { await runSave(async () => { await cabinlingoApi.createOrganization(organizationForm); Object.assign(organizationForm, { code: '', name: '' }) }, '组织保存失败，编码可能已存在') } async function saveCourse() { await runSave(async () => { selectedCourse.value = await cabinlingoApi.createCourse({ ...courseForm, category: 'broadcast', organization_id: courseForm.organization_id || null }); Object.assign(courseForm, { code: '', title: '', description: '', organization_id: '' }) }, '课程保存失败，编码可能已存在') }
async function saveVersion() { if (!selectedCourse.value) return; await runSave(async () => { await cabinlingoApi.createCourseVersion(selectedCourse.value!.id, versionForm); versions.value = await cabinlingoApi.courseVersions(selectedCourse.value!.id); Object.assign(versionForm, { version_label: `V1.${versions.value.length}`, change_summary: '' }) }, '版本保存失败，版本标识可能已存在') } async function saveChapter() { if (!selectedVersion.value) return; await runSave(async () => { await cabinlingoApi.createChapter(selectedVersion.value!.id, chapterForm); chapters.value = await cabinlingoApi.chapters(selectedVersion.value!.id); Object.assign(chapterForm, { code: '', title: '', sequence_no: chapters.value.length + 1, learning_objective: '' }) }, '篇目保存失败，编码或顺序可能重复') }
async function saveHtml() { if (!selectedChapter.value || !htmlForm.source_html) { dialogError.value = '请选择 HTML 文件'; return } await runSave(async () => { const created = await cabinlingoApi.importHtml(selectedChapter.value!.id, htmlForm); contents.value = await cabinlingoApi.contents(selectedChapter.value!.id); await selectContent(created) }, 'HTML 导入失败；请检查文件大小、安全内容和显示顺序') } async function savePpt() { if (!selectedVersion.value || !pptFile.value) { dialogError.value = '请选择 PPTX 文件'; return } await runSave(async () => { const result = await cabinlingoApi.importPpt(selectedVersion.value!.id, pptFile.value!); versions.value = await cabinlingoApi.courseVersions(selectedCourse.value!.id); selectedVersion.value = versions.value.find(item => item.id === result.course_version_id) || selectedVersion.value; chapters.value = await cabinlingoApi.chapters(result.course_version_id); selectedChapter.value = chapters.value.find(item => item.id === result.chapter_id) || null; contents.value = selectedChapter.value ? await cabinlingoApi.contents(selectedChapter.value.id) : []; await selectContent(contents.value[0] || null); pptFile.value = null }, 'PPTX 导入失败；请确认当前是草稿版本、文件为有效 .pptx 且未重复导入') } async function saveStandard() { if (!selectedContent.value) return; await runSave(async () => { let saved = await cabinlingoApi.saveCourseStandard(selectedContent.value!.id, standardForm); if (standardAudioFile.value) saved = await cabinlingoApi.uploadCourseStandardAudio(selectedContent.value!.id, saved.id, standardAudioFile.value); selectedStandard.value = saved; standardAudioFile.value = null }, '课程训练标准保存失败；请检查文本、音频格式和课程版本状态') }
async function saveInteraction() { if (!selectedContent.value) return; const options = interactionOptionsText.value.split(/\r?\n/).map(value => value.trim()).filter(Boolean); const acceptedAnswers = interactionAnswersText.value.split(/\r?\n/).map(value => value.trim()).filter(Boolean); const payload = { ...interactionForm, options, accepted_answers: acceptedAnswers }; await runSave(async () => { if (editingInteraction.value) await cabinlingoApi.updateContentInteraction(editingInteraction.value.id, payload); else await cabinlingoApi.createContentInteraction(selectedContent.value!.id, payload); interactions.value = await cabinlingoApi.contentInteractions(selectedContent.value!.id); editingInteraction.value = null; Object.assign(interactionForm, { prompt: '', options: [], correct_answer: '', accepted_answers: [] }) }, '互动保存失败；选择/点击互动至少要有两个选项且正确答案必须匹配') }
async function saveUser() { await runSave(async () => { await cabinlingoApi.createUser({ ...userForm, class_id: userForm.class_id || undefined }); Object.assign(userForm, { account: '', display_name: '', password: '', role: 'learner', class_id: '' }) }, '账号保存失败，账号可能存在或密码不符合要求') }
async function saveTask() { if (taskForm.sourceMode === 'broadcast' && !taskForm.broadcastScriptIds.length) { dialogError.value = '请至少选择一篇广播词'; return } await runSave(async () => { const source = taskForm.sourceMode === 'course' ? { course_version_id: taskForm.courseVersionId, broadcast_script_id: null, broadcast_script_ids: null, broadcast_id: null } : { broadcast_script_ids: [...taskForm.broadcastScriptIds], broadcast_script_id: null, course_version_id: null, broadcast_id: null }; const due_at = taskForm.dueAt ? new Date(taskForm.dueAt).toISOString() : null; const task = taskForm.type === 'practice' ? await cabinlingoApi.createPracticeTask({ title: taskForm.title, ...source, due_at, completion_rule: { min_attempts: taskForm.minAttempts } }) : await cabinlingoApi.createExamTask({ title: taskForm.title, ...source, due_at, max_recordings: taskForm.maxRecordings }); if (taskForm.userIds.length || taskForm.classIds.length) await cabinlingoApi.batchAssign(taskForm.type, task.id, taskForm.userIds, taskForm.classIds) }, '任务创建失败；请确认所选广播词保持启用且内容完整，课程版本必须先发布') }
async function changeTaskStatus(task: TaskListItem, action: 'publish' | 'close') { try { await cabinlingoApi.updateTaskStatus(task.task_type, task.id, action); await refreshAll() } catch (cause) { pageError.value = '任务状态更新失败'; console.error(cause) } }
async function deleteTask(task: TaskListItem) { if (!window.confirm(`确认删除任务“${task.title}”吗？删除后管理端和学员端将立即停止显示，且不能在页面恢复。`)) return; try { await cabinlingoApi.deleteTask(task.task_type, task.id); await refreshAll() } catch (cause) { pageError.value = '任务删除失败'; console.error(cause) } }
function handleEscape(event: KeyboardEvent) { if (event.key === 'Escape' && dialog.value) closeDialog() }
onMounted(() => { window.addEventListener('keydown', handleEscape); void refreshAll(); void loadAIStatus() })
onBeforeUnmount(() => { window.removeEventListener('keydown', handleEscape); clearStandardAudio() })
</script>

